import json, re
base="<repo>/.arena/runs/fmc-mcp-decomposition-20260617T195758Z/snapshot-ddb951deca8d5c7b/"
m=json.load(open(base+"project-model-v1.json"))
s=json.dumps(m)
print("TOP KEYS:", list(m.keys()))
print("stdio:", s.lower().count("stdio"), "sse:", s.lower().count("sse"), "http:", s.lower().count("http"))

# collect provenance ref ids declared and referenced
refs=set(re.findall(r'prov:[0-9a-f]+', s))
print("distinct prov refs referenced:", len(refs))
# find a provenance index/table
for k in m.keys():
    if 'prov' in k.lower():
        print("prov key:", k, type(m[k]))

# components: find list with priorityRank
def find_components(o):
    out=[]
    if isinstance(o,dict):
        if 'priorityRank' in o and ('componentId' in o or 'id' in o):
            out.append(o)
        for v in o.values(): out+=find_components(v)
    elif isinstance(o,list):
        for v in o: out+=find_components(v)
    return out
comps={}
for c in find_components(m):
    cid=c.get('componentId') or c.get('id')
    comps[cid]=c
for cid,c in sorted(comps.items(), key=lambda x:x[1].get('priorityRank',99)):
    files=c.get('files') or c.get('paths') or c.get('modules') or c.get('members') or c.get('memberPaths')
    print(c.get('priorityRank'), cid, "files=", files)

